const SCORE_DIMENSIONS=["factual-correctness","consequential-information-coverage","specificity","causal-depth","temporal-understanding","epistemic-calibration","actionability","provenance-inspectability","compression-without-meaning-loss","surprise-value","executive-usefulness"] as const;
const ANALYSIS_QUALITY=["factual-correctness","consequential-coverage","specificity","causal-depth","temporal-understanding","contradiction-handling","epistemic-calibration","actionability","compression","surprise-value","executive-usefulness"] as const;
const PLATFORM_VALUE=["provenance-inspectability","source-access-awareness","permission-awareness","chronology-preservation","continuity-across-meetings","reviewed-organizational-memory","private-versus-governed-separation","update-rather-than-rewrite-history"] as const;
