type DraftScore={dimensions:Record<string,number>;disposition:StudioScorecardV1["disposition"];comments:string};
const scoreFrom=(value:StudioScorecardV1):DraftScore=>({dimensions:value.dimensions,disposition:value.disposition,comments:value.comments??""});
const newScore=():DraftScore=>({dimensions:Object.fromEntries(SCORE_DIMENSIONS.map(x=>[x,3])),disposition:"Better but incomplete",comments:""});
const blindScore=()=>({analysisQuality:Object.fromEntries(ANALYSIS_QUALITY.map(key=>[key,{rating:3 as const,comment:null}])),platformValue:Object.fromEntries(PLATFORM_VALUE.map(key=>[key,{rating:"not-applicable" as const,comment:null}])),comments:null});
const terminalMessage=(run:FrontierRunV1)=>run.terminalMetadata?.category==="terminal-incomplete-max-output-tokens"?"Frontier run incomplete — the configured output/reasoning budget was exhausted before a complete structured result was produced.":run.terminalMetadata?.category??(run.terminal==="complete"?"terminal-success":"terminal-unavailable-other");
function FounderOutput({run}:{run:FrontierRunV1}){const output=run.terminal==="complete"?run.output:run.semanticRejection?.output,banner=run.terminalMetadata?.category==="terminal-semantic-validation-failed"?<><p role="alert"><strong>Frontier analysis rejected by semantic checks — not benchmark eligible</strong></p>{run.semanticRejection?<details><summary>Inspect exact findings</summary>{run.semanticRejection.findings.filter(finding=>finding.result==="fail").map(finding=><p key={finding.findingDigest}><strong>{finding.ruleId}</strong> · {finding.objectPath} · {finding.reasonCategory}</p>)}</details>:null}</>:null;if(!output)return <>{banner}<p>D — Historical semantic-failure details unavailable under the prior contract.</p></>;if(typeof output==="string")return <>{banner}<p>{output}</p></>;if("objects" in output){const groups=["attention-item","observation","assessment","decision","non-decision","commitment","open-question","resolved-unknown","contradiction","recommendation"] as const;return <>{banner}<section><h4>What matters now</h4><p>{output.executiveBrief}</p></section>{groups.map(kind=>{const items=output.objects.filter(item=>item.kind===kind);return items.length?<section key={kind}><h4>{kind.replaceAll("-"," ")}</h4>{items.map((item,index)=><article key={`${kind}-${index}`}><p>{item.statement}</p><small>Sources: {item.sourceEventIds.join(", ")||"none"}</small></article>)}</section>:null})}<section><h4>Attention next</h4><p>{output.attentionRecommendation}</p></section></>};return <>{banner}<section><h4>What matters now</h4><p>{output.executiveSynthesis}</p></section>{[["Why it matters",output.whyItMatters],["Decisions",output.decisions],["Commitments",output.commitments],["Unknowns",output.unknowns],["Contradictions",output.contradictions]].map(([label,items])=><section key={label as string}><h4>{label as string}</h4>{(items as string[]).map(item=><p key={item}>{item}</p>)}</section>)}<section><h4>Attention next</h4><p>{output.attentionRecommendation}</p></section></>}
function FounderStudioOutput({run}:{run:StudioRunV1}){return <><section><h4>Prepare</h4><p>{run.presentation.prepare?.meeting.title??run.presentation.prepareUnavailableReason??"Unavailable"}</p>{run.presentation.prepare?.whatMattersNow.map(item=><p key={item}>{item}</p>)}</section><section><h4>Review</h4>{run.presentation.review.map(item=><p key={item.candidateId}>{item.statement}</p>)}</section><section><h4>Closure</h4>{run.presentation.closure.sections.flatMap(section=>section.items).map(item=><p key={item}>{item}</p>)}</section><section><h4>What changed</h4>{run.presentation.whatChanged.items.map((item,index)=><p key={`${item.kind}-${index}`}>{item.statement}</p>)}</section></>}
const FounderEvidence=({references}:{references:FounderReviewAnalysisV1["whatMattersNowEvidence"]})=>references.length?<small>Sources: {references.map(reference=>`${reference.sourceTitle} (${reference.sourceEventId})`).join("; ")}</small>:null;
function FounderBlindOutput({analysis}:{analysis:FounderReviewAnalysisV1}){return <><section><h4>What matters now</h4><p>{analysis.whatMattersNow}</p><FounderEvidence references={analysis.whatMattersNowEvidence}/></section>{analysis.sections.map(section=><section key={section.label}><h4>{section.label}</h4>{section.items.length?<>{section.items.map((item,index)=><article key={`${section.label}-${index}`}><p>{item.statement}</p><FounderEvidence references={item.evidenceReferences}/></article>)}{section.items.every(item=>item.evidenceReferences.length===0)?<p>Source detail is unavailable for this section.</p>:null}</>:<p>Not established from the available information</p>}</section>)}{analysis.limitations.length?<section><h4>Limitations</h4>{analysis.limitations.map(item=><p key={item}>{item}</p>)}</section>:null}</>}

